//! The bundled emulator catalog: `assets/emulators.json`, generated by
//! `tools/build_catalog.py` from ES-DE's system definitions and libretro's core info files.
//! Loaded into SQLite at startup so the UI can query it.

use std::collections::HashMap;

use anyhow::{Context, Result};
use serde::Deserialize;

const BUNDLED: &str = include_str!("../assets/emulators.json");

#[derive(Debug, Deserialize)]
pub struct CatalogFile {
    pub generated: String,
    pub systems: Vec<CatalogSystem>,
    pub emulators: Vec<CatalogEmulator>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct CatalogSystem {
    pub id: String,
    pub name: String,
    /// Which systems are the same hardware under different names (tg16 and pcengine), so the
    /// library keeps their media in one folder. Taken from ES-DE's `<platform>` tag; the final
    /// group is `platforms::media_group`, after the adjustments in assets/platforms.toml.
    pub media_group: String,
    /// Every `.bin` on this system should be a cue sheet's track (see `scan::lone_bins`).
    #[serde(default)]
    pub bin_is_cue_track: bool,
}

#[derive(Debug, Clone, Deserialize)]
pub struct CatalogEmulator {
    pub id: String,
    pub name: String,
    /// "retroarch" or "standalone"
    pub kind: String,
    /// RetroArch's save folder for this core when "sort saves by core" is on.
    #[serde(default)]
    pub corename: Option<String>,
    pub systems: Vec<String>,
}

pub fn bundled() -> Result<CatalogFile> {
    serde_json::from_str(BUNDLED).context("parse bundled assets/emulators.json")
}

/// An emulator as the UI shows it: from the catalog or a custom one.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EmulatorInfo {
    pub id: String,
    pub name: String,
    pub kind: Kind,
    pub corename: Option<String>,
}

/// Every emulator RomServer knows, by id: the bundled catalog plus the user's custom ones.
/// Built from the bundled file rather than the database, so planning never sees an empty list
/// (which would read as "no emulators" and drop every save projection).
pub fn index(settings: &crate::settings::Settings) -> Result<HashMap<String, EmulatorInfo>> {
    let mut out: HashMap<String, EmulatorInfo> = bundled()?
        .emulators
        .into_iter()
        .map(|e| {
            let info = EmulatorInfo {
                id: e.id.clone(),
                name: e.name,
                kind: Kind::from_catalog(&e.kind),
                corename: e.corename,
            };
            (e.id, info)
        })
        .collect();
    for (id, custom) in &settings.custom_emulators {
        out.insert(
            id.clone(),
            EmulatorInfo {
                id: id.clone(),
                name: custom.name.clone(),
                kind: Kind::Custom,
                corename: None,
            },
        );
    }
    Ok(out)
}

/// Borrows an index the way the planners take it.
pub fn by_id(index: &HashMap<String, EmulatorInfo>) -> HashMap<&str, &EmulatorInfo> {
    index.iter().map(|(id, e)| (id.as_str(), e)).collect()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    RetroArch,
    Standalone,
    Custom,
}

impl Kind {
    pub fn from_catalog(kind: &str) -> Self {
        if kind == "retroarch" {
            Kind::RetroArch
        } else {
            Kind::Standalone
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Kind::RetroArch => "RetroArch core",
            Kind::Standalone => "Standalone",
            Kind::Custom => "Custom",
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bundled_catalog_parses_and_covers_the_basics() {
        let c = bundled().unwrap();
        assert!(c.systems.iter().any(|s| s.id == "psx"));
        let snes9x = c.emulators.iter().find(|e| e.id == "ra-snes9x").unwrap();
        assert_eq!(snes9x.corename.as_deref(), Some("Snes9x"));
        assert!(snes9x.systems.contains(&"snes".to_string()));
        let mednafen = c.emulators.iter().find(|e| e.id == "mednafen").unwrap();
        assert!(
            mednafen.systems.len() > 10,
            "multi-system emulators appear once"
        );
        assert!(!c.emulators.iter().any(|e| e.id == "os-shell"));
    }
}
